/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getDatum = require( './datum/get.js' );
var setDatum = require( './datum/set.js' );

var getGroup = require( './group/get.js' );
var setGroup = require( './group/set.js' );

var getLevel = require( './level/get.js' );
var setLevel = require( './level/set.js' );

var getParent = require( './parent/get.js' );
var setParent = require( './parent/set.js' );

var getProperties = require( './properties/get.js' );

var getSignal = require( './signal/get.js' );
var setSignal = require( './signal/set.js' );


// VARIABLES //

var debug = logger( 'vega:value:field-descriptor:main' );


// MAIN //

/**
* Field descriptor constructor.
*
* ## Notes
*
* -   Field lookups may be arbitrarily nested in order to perform _indirect_ field lookups (e.g., `{ 'parent': { 'datum': 'f' } }` first retrieves field `f` from the current mark's data and then uses the resolved value as a property name on the parent's data object).
*
* @constructor
* @param {Options} [options] - constructor options
* @param {(string|FieldDescriptor)} [options.datum] - field lookup on the current data object
* @param {(string|FieldDescriptor)} [options.group] - field lookup on the enclosing group mark instance
* @param {PositiveInteger} [options.level=1] - nesting level for `group` and `parent` references
* @param {(string|FieldDescriptor)} [options.parent] - field lookup on the enclosing group mark's data object
* @param {string} [options.signal] - signal name or expression to evaluate and use as the field name to lookup
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {FieldDescriptor} field descriptor instance
*
* @example
* var descriptor = new FieldDescriptor();
* // returns <FieldDescriptor>
*/
function FieldDescriptor( options ) {
	var nargs;
	var opts;
	var keys;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof FieldDescriptor ) ) {
		if ( nargs ) {
			return new FieldDescriptor( options );
		}
		return new FieldDescriptor();
	}
	EventEmitter.call( this );

	// Set internal properties to undefined...
	for ( i = 0; i < properties.length; i++ ) {
		this[ '_'+properties[ i ] ] = void 0;
	}
	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( FieldDescriptor, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof FieldDescriptor
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( FieldDescriptor, 'name', 'FieldDescriptor' );

/**
* Returns a boolean indicating if a value is a field descriptor instance.
*
* ## Notes
*
* -   This method is intended for use within this class only and is present in order to avoid a circular dependency on `@stdlib/plot/vega/base/assert/is-value-field-descriptor`. The method should use the same brand checks.
*
* @private
* @name _isFieldDescriptor
* @memberof FieldDescriptor.prototype
* @param {*} value - value to test
* @returns {boolean} boolean indicating if a value is a field descriptor instance
*/
setNonEnumerableReadOnly( FieldDescriptor.prototype, '_isFieldDescriptor', function isFieldDescriptor( value ) {
	return (
		value instanceof FieldDescriptor ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			(
				hasProp( value, 'datum' ) ||
				hasProp( value, 'group' ) ||
				hasProp( value, 'parent' ) ||
				hasProp( value, 'signal' )
			)
		)
	);
});

/**
* Field lookup on the current data object.
*
* @name datum
* @memberof FieldDescriptor.prototype
* @type {(string|FieldDescriptor|void)}
* @default undefined
*
* @example
* var descriptor = new FieldDescriptor({
*     'datum': 'price'
* });
*
* var v = descriptor.datum;
* // returns 'price'
*/
setReadWriteAccessor( FieldDescriptor.prototype, 'datum', getDatum, setDatum );

/**
* Field lookup on the enclosing group mark instance.
*
* @name group
* @memberof FieldDescriptor.prototype
* @type {(string|FieldDescriptor|void)}
* @default undefined
*
* @example
* var descriptor = new FieldDescriptor({
*     'group': 'width'
* });
*
* var v = descriptor.group;
* // returns 'width'
*/
setReadWriteAccessor( FieldDescriptor.prototype, 'group', getGroup, setGroup );

/**
* Nesting level for `group` and `parent` references.
*
* @name level
* @memberof FieldDescriptor.prototype
* @type {(PositiveInteger|void)}
* @default 1
*
* @example
* var descriptor = new FieldDescriptor({
*     'parent': 'price',
*     'level': 2
* });
*
* var v = descriptor.level;
* // returns 2
*/
setReadWriteAccessor( FieldDescriptor.prototype, 'level', getLevel, setLevel );

/**
* Field lookup on the enclosing group mark's data object.
*
* @name parent
* @memberof FieldDescriptor.prototype
* @type {(string|FieldDescriptor|void)}
* @default undefined
*
* @example
* var descriptor = new FieldDescriptor({
*     'parent': 'price'
* });
*
* var v = descriptor.parent;
* // returns 'price'
*/
setReadWriteAccessor( FieldDescriptor.prototype, 'parent', getParent, setParent );

/**
* Field descriptor properties.
*
* @name properties
* @memberof FieldDescriptor.prototype
* @type {Array<string>}
*
* @example
* var descriptor = new FieldDescriptor();
*
* var v = descriptor.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( FieldDescriptor.prototype, 'properties', getProperties );

/**
* Signal name or expression to evaluate and use as the field name to lookup.
*
* @name signal
* @memberof FieldDescriptor.prototype
* @type {(string|void)}
* @default undefined
*
* @example
* var descriptor = new FieldDescriptor({
*     'signal': 'fieldName'
* });
*
* var v = descriptor.signal;
* // returns 'fieldName'
*/
setReadWriteAccessor( FieldDescriptor.prototype, 'signal', getSignal, setSignal );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof FieldDescriptor.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var descriptor = new FieldDescriptor({
*     'datum': 'price'
* });
*
* var json = descriptor.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( FieldDescriptor.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = FieldDescriptor;
